 if(!identity.value||!from.value||!to.value||!until.value||v.leader_actor_id!=p.leader_actor_id||!same(v.execution_source,p.execution_source)||!same_refs(v.actual_anchor_sources,p.actual_anchor_sources)||v.reason!=p.reason||v.reason_source.has_value()!=p.reason_source.has_value()||(v.reason_source&&!same(*v.reason_source,*p.reason_source))||p.credited_half_days<0||p.credited_half_days>1)return common_failure("WorkReceiptOriginalMismatch",p.fact_id);
 Integer prior=0;bool found=false;for(const auto&id:e.accepted_period_refs){if(id==p.fact_id){found=true;break;}const auto*old=state.period_receipts.find(id);if(!old||old->work_id!=e.work_id||old->credited_half_days<0||old->credited_half_days>1||prior>required(e.frozen_plan)-old->credited_half_days)return common_failure("WorkReceiptOrderCorrupt",p.fact_id);prior+=old->credited_half_days;}
 if(!found)return common_failure("UnreferencedWorkPeriod",p.fact_id);const auto&gate=deadline(e.frozen_plan);auto timely=calendar_deadline_accepts(gate.tick,gate.inclusive,p.actual_until);if(!timely.ok)return {false,{},timely.error};const Integer credit=v.source_provided&&timely.value&&prior<required(e.frozen_plan)?1:0;auto whole=same_moment(p.actual_until,p.window.to);if(!whole.ok)return {false,{},whole.error};const auto expected=credit?S3WorkPeriodDisposition::credited:!whole.value||v.reason==WorkPeriodReason::source_interrupted?S3WorkPeriodDisposition::interrupted:S3WorkPeriodDisposition::not_credited;
 return p.credited_half_days==credit&&p.disposition==expected?common_success():common_failure("WorkReceiptCreditMismatch",p.fact_id);
